class PanelQuad;

class stringx
{
public:
    void printf(const char *format, ...);
    const char *c_str() const;
};

class CheatFrontEnd
{
private:
    char base_layout[0x160];
    void *sys;
    bool pq_indices_set;
    char pq_indices_padding[3];
    PanelQuad *arrow_up[2];
    PanelQuad *arrow_down[2];
    PanelQuad *cellphone;
    PanelQuad *numbers[10];
    PanelQuad *numbers_hi[10];

    PanelQuad *GetPointer(const char *name);

public:
    void SetPQIndices();
};

void CheatFrontEnd::SetPQIndices()
{
	stringx number_name;

	if(!pq_indices_set)
	{
		arrow_up[0] = GetPointer("btn_up_off");
		arrow_up[1] = GetPointer("btn_up_on");
		arrow_down[0] = GetPointer("btn_down_off");
		arrow_down[1] = GetPointer("btn_down_on");
		cellphone = GetPointer("cellphone");

		for(int i = 0; i < 10; i++)
		{
			number_name.printf("key_%d_yellow", i);
			numbers[i] = GetPointer(number_name.c_str());
			number_name.printf("key_%d_green", i);
			numbers_hi[i] = GetPointer(number_name.c_str());
		}

		pq_indices_set = true;
	}
}
